Tr.Begin();
int min = 0;
Tr.S("min يبدأ من 0 — انتبه لهذه القيمة.", "min", min);
int x = int.Parse(Console.ReadLine());
Tr.S("نقرأ أول عدد.", "x", x);
while (x != 0)
{
    Tr.At(3, "الشرط صحيح: ندخل الحلقة.", "x != 0", x != 0);
    Tr.At(5, x < min ? "x أصغر من min." : "x ليس أصغر من min = 0: لا يتغير شيء.", "x < min", x < min);
    if (x < min)
    { //~
        min = x;
        Tr.S("min يتغير.", "min", min);
    } //~
    x = int.Parse(Console.ReadLine());
    Tr.S("نقرأ العدد التالي.", "x", x);
}
Tr.At(3, "الشرط خطأ: نخرج من الحلقة.", "x != 0", x != 0);
Console.WriteLine(min);
Tr.S("الطباعة: 0، مع أن 0 ليس من الأعداد. هذا هو الفخّ.");
Tr.End();

Tr.Begin();
int n = 4827, sum = 0;
Tr.S("نبدأ بالعدد والمجموع صفر.", "n", n, "sum", sum);
while (n > 0)
{
    int d = n % 10;
    Tr.S("نأخذ الآحاد.", "d", d);
    Tr.At(5, d % 2 == 0 ? "زوجية: نضيفها." : "فردية: نتجاوزها.", "d % 2", d % 2);
    if (d % 2 == 0)
    { //~
        sum += d;
        Tr.S("نضيف d إلى المجموع.", "sum", sum);
    } //~
    n /= 10;
    Tr.S("نحذف الآحاد.", "n", n);
}
Tr.Drop("d");
Tr.At(2, "لم تبقَ منازل: نخرج من الحلقة.", "n > 0", n > 0);
Console.WriteLine(sum);
Tr.S("الطباعة: 14.");
Tr.End();
